  "dart-public-types":
    "/// A fully resolved prompt ready to be sent to an LLM.\n///\n/// The [Output] type parameter is the parsed response type for the template.\n/// The [ToolExecutor] type parameter is the object whose methods implement the\n/// template's tools, or [NoTools] when no tools are available.\n///\n/// Build and send the API request using [systemMessage], [userMessage],\n/// [examples], and [tools]. If the model requests tool calls, dispatch\n/// them with [executeTools] and then parse the final response with\n/// [parseResponse].\nfinal class Prompt<Output, ToolExecutor> {\n  /// Metadata for this prompt.\n  final Meta meta;\n  final String systemMessage;\n  final String userMessage;\n\n  /// Few-shot examples.\n  final UnmodifiableListView<FewShotExample> examples;\n\n  /// The tools which can be called by the LLM, keyed by tool name.\n  final UnmodifiableMapView<String, Tool> tools;\n  final OutputFormat outputFormat;\n  final TemplateId templateId;\n  final Output Function(dynamic json) _fromJson;\n\n  const Prompt({\n    required this.meta,\n    required this.systemMessage,\n    required this.userMessage,\n    required this.examples,\n    required this.tools,\n    required this.outputFormat,\n    required this.templateId,\n    required Output Function(dynamic json) fromJson,\n  }) : _fromJson = fromJson;\n\n  /// Parse an LLM response into the expected output type.\n  Output parseResponse(String response) {\n    return _doParseResponse<Output>(\n      response,\n      outputFormat,\n      templateId,\n      _fromJson,\n    );\n  }\n\n  /// Execute the given tool calls in parallel.\n  Future<List<ToolCallResponse>> executeTools(\n    Iterable<ToolCall> toolCalls,\n    ToolExecutor toolExecutor,\n  ) async {\n    final namespace = templateId.toString().split(':')[0];\n    return Future.wait(\n      toolCalls.map(\n        (call) => _executeToolCall(call, namespace, toolExecutor as Object),\n      ),\n    );\n  }\n}\n\n/// The expected format of the model output.\n/// One of [JsonOutputFormat] or [TextOutputFormat].\nsealed class OutputFormat {\n  const OutputFormat();\n}\n\nfinal class JsonOutputFormat extends OutputFormat {\n  final String stringifiedJsonSchema;\n  final UnmodifiableMapView<String, dynamic> jsonSchema;\n\n  const JsonOutputFormat._({\n    required this.stringifiedJsonSchema,\n    required this.jsonSchema,\n  });\n}\n\nfinal class TextOutputFormat extends OutputFormat {\n  const TextOutputFormat();\n}\n\nfinal class Tool {\n  final String name;\n  final String description;\n  final UnmodifiableMapView<String, dynamic> inputJsonSchema;\n\n  const Tool({\n    required this.name,\n    required this.description,\n    required this.inputJsonSchema,\n  });\n}\n\n/// A single few-shot example consisting of a user message, optional intermediate\n/// tool-call steps, and the expected response.\nfinal class FewShotExample {\n  final String userMessage;\n  final UnmodifiableListView<IntermediateStepExample> intermediateSteps;\n  final String response;\n\n  const FewShotExample({\n    required this.userMessage,\n    required this.intermediateSteps,\n    required this.response,\n  });\n}\n\n/// One intermediate step within a few-shot example, containing the tool\n/// calls made at that step.\nfinal class IntermediateStepExample {\n  /// Tool calls made in parallel at this step.\n  final UnmodifiableListView<ToolCallExample> toolCalls;\n\n  const IntermediateStepExample({\n    required this.toolCalls,\n  });\n}\n\n/// A single tool call recorded inside an intermediate step.\nfinal class ToolCallExample {\n  final String callId;\n  final String toolName;\n  final String stringifiedInput;\n  final String stringifiedOutput;\n\n  const ToolCallExample({\n    required this.callId,\n    required this.toolName,\n    required this.stringifiedInput,\n    required this.stringifiedOutput,\n  });\n}\n\nfinal class ToolCall {\n  final String callId;\n  final String toolName;\n  final String stringifiedInput;\n\n  const ToolCall({\n    required this.callId,\n    required this.toolName,\n    required this.stringifiedInput,\n  });\n}\n\nfinal class ToolCallResponse {\n  final String callId;\n  final String stringifiedOutput;\n\n  const ToolCallResponse({\n    required this.callId,\n    required this.stringifiedOutput,\n  });\n}\n\nfinal class NoTools {\n  const NoTools._();\n}\n\nconst noTools = NoTools._();",
